const env = (k, d = '') => { const v = $env[k]; return (v === undefined || v === null || v === '') ? d : String(v); };
const clean = (items) => (items || []).map(i => (i && i.json !== undefined) ? i.json : i)
  .filter(j => j && typeof j === 'object' && Object.values(j).some(v => v !== '' && v !== null && v !== undefined));
const blockedCountries = () => { const s = new Set(env('BLOCKED_COUNTRIES', 'CR').split(',').map(x => x.trim().toUpperCase()).filter(Boolean)); s.add('CR'); return s; };
const domainOf = (e) => { const m = String(e || '').toLowerCase().match(/@([a-z0-9.-]+)/); return m ? m[1] : ''; };
const domainOfUrl = (u) => { try { if (!u) return ''; const h = new URL(/^https?:\/\//i.test(u) ? u : 'http://' + u).hostname.toLowerCase(); return h.replace(/^www\./, ''); } catch (e) { return ''; } };
const FREE_MAIL = new Set(['gmail.com','googlemail.com','seznam.cz','email.cz','centrum.cz','volny.cz','atlas.cz','post.cz','tiscali.cz','yahoo.com','yahoo.co.uk','yahoo.ca','yahoo.com.au','hotmail.com','hotmail.co.uk','outlook.com','live.com','icloud.com','me.com','aol.com','protonmail.com','proton.me','mail.com','gmx.com','gmx.de','web.de','bigpond.com','shaw.ca','telus.net','rogers.com','comcast.net','att.net','verizon.net','btinternet.com','sky.com','virginmedia.com']);
const parseISO = (s) => { if (!s) return null; const d = DateTime.fromISO(String(s)); return d.isValid ? d : null; };
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const truthy = (v) => ['true', '1', 'yes', 'ano'].includes(String(v ?? '').trim().toLowerCase());

const crypto = require('crypto');
const q = ($input.first().json || {}).query || {};
const id = String(q.id || '').trim();
const t = String(q.t || '').trim();
const secret = env('UNSUB_SECRET', '');
let valid = false;
if (id && t && secret) {
  const expected = crypto.createHmac('sha256', secret).update(id).digest('hex').slice(0, 24);
  valid = expected.length === t.length && crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(t));
}
return [{ json: { id, valid, lang_hint: String(q.lang || '') } }];

